package main

import (
	"testing"
)

func TestPostAlbumCountRace(t *testing.T) {
	// Reset albumCounts
	albumCounts = []albumCount{}

	// Create a new album count entry
	albumCounts = append(albumCounts, albumCount{ID: "1", Count: 0})
	index := 0

	// Simulate the race condition from postAlbumCount
	for i := 0; i < 10000; i++ {
		go func() {
			current := albumCounts[index].Count
			albumCounts[index].Count = current + 1
		}()
	}
}

package main

import (
	"sync"
	"testing"
)

func TestPostAlbumCountRace(t *testing.T) {
	// Reset albumCounts
	albumCounts = []albumCount{}

	// Create a new album count entry
	albumCounts = append(albumCounts, albumCount{ID: "1", Count: 0})
	index := 0

	// Simulate the race condition from postAlbumCount
	var wg sync.WaitGroup
	for i := 0; i < 10000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			current := albumCounts[index].Count
			albumCounts[index].Count = current + 1
		}()
	}
	wg.Wait()

	// The count should be 10000, but due to race it will be less
	t.Logf("Final count: %d (expected 10000)", albumCounts[index].Count)
}

